/// The most units one craft may ask for.
pub const CRAFT_MAX_COUNT: u32 = 100;

/// The station kind stored as `wire`.
pub fn station(wire: u8) -> Option<&'static StationData> {
    STATIONS.get(usize::from(wire))
}

/// The station kind with content id `id`.
pub fn station_by_id(id: &str) -> Option<&'static StationData> {
    STATIONS.iter().find(|d| d.id == id)
}

/// The recipe stored as `wire`.
pub fn recipe(wire: u16) -> Option<&'static RecipeData> {
    RECIPES.get(usize::from(wire))
}

/// The recipe with content id `id`.
pub fn recipe_by_id(id: &str) -> Option<&'static RecipeData> {
    RECIPES.iter().find(|d| d.id == id)
}

/// Crop kinds (`content/farming.toml`, docs/design/farming.md). The discriminant is the wire value.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum CropKind {
    Crop = 0,
    Tree = 1,
    Animal = 2,
}

/// What grows from a seed: a crop, tree or animal (`content/farming.toml`, docs/design/farming.md).
#[derive(Debug, PartialEq)]
pub struct CropData {
    /// Stored in crop rows.
    pub wire: u8,
    pub id: &'static str,
    /// What players see.
    pub name: &'static str,
    pub kind: CropKind,
    /// The wire of the seed item that plants it.
    pub seed: u16,
    /// The wire of its ideal climate.
    pub climate: u8,
    /// Seconds to mature outside its ideal climate.
    pub grow_s: u32,
    /// The wire of the item a harvest gives, and how many, inclusive.
    pub product: u16,
    pub yield_min: u32,
    pub yield_max: u32,
    /// Labor spent on each harvest.
    pub labor: i32,
    /// Seconds until it's ripe again after a harvest; 0 if a harvest removes it.
    pub regrow_s: u32,
    /// Seconds it stays ripe before it withers; 0 if it never does.
    pub wither_s: u32,
    /// Its radius on the ground, m.
    pub space_m: f32,
    /// It may only be planted on a plot.
    pub plot_only: bool,
    /// The chance, in percent, that a harvest also gives one of its seed.
    pub seed_pct: u32,
}

